import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.57.4';
const supabase = createClient(window.TV_GUIDE_SUPABASE.url, window.TV_GUIDE_SUPABASE.publishableKey);
let submissions = [], selected = null;
const $ = id => document.getElementById(id);
function message(text, kind='') { $('adminMessage').textContent = text; $('adminMessage').dataset.kind = kind; }
function esc(value) { return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])); }
function renderList() { $('submissionCount').textContent = submissions.length; $('submissionList').innerHTML = submissions.length ? submissions.map(p => `<button class="submission-item ${selected?.id === p.id ? 'active' : ''}" data-id="${p.id}"><strong>${esc(p.first_name)} ${esc(p.last_name)}</strong><span>${esc(p.practice_name || 'Independent practice')}</span><small>${new Date(p.submitted_at).toLocaleDateString()}</small></button>`).join('') : '<p class="muted">No profiles are waiting for review.</p>'; document.querySelectorAll('.submission-item').forEach(b => b.addEventListener('click', () => selectSubmission(b.dataset.id))); }
function renderDetail() { if (!selected) { $('emptyReview').hidden = false; $('reviewCard').hidden = true; return; } $('emptyReview').hidden = true; $('reviewCard').hidden = false; $('reviewName').textContent = `${selected.first_name} ${selected.last_name}${selected.credentials ? `, ${selected.credentials}` : ''}`; $('reviewPractice').textContent = `${selected.practice_name || 'Independent practice'} · ${selected.primary_city}`; $('reviewStatus').textContent = selected.status; const rows = [['Bio', selected.short_bio],['Website', selected.website_url ? `<a href="${esc(selected.website_url)}" target="_blank" rel="noreferrer">${esc(selected.website_url)}</a>` : '—'],['YouTube video', selected.video_url ? `<a href="${esc(selected.video_url)}" target="_blank" rel="noreferrer">${esc(selected.video_url)}</a>` : '—'],['Client portal', selected.client_portal_url ? `<a href="${esc(selected.client_portal_url)}" target="_blank" rel="noreferrer">${esc(selected.client_portal_url)}</a>` : '—'],['Public QR codes', [selected.show_website_qr ? 'Website' : '', selected.show_portal_qr ? 'Portal / scheduling' : ''].filter(Boolean).join(', ') || 'None'],['Availability', selected.availability],['Visit type', (selected.visit_types || []).join(', ') || '—'],['Provider gender', selected.provider_gender || '—'],['State license', selected.license_number ? `${esc(selected.license_state || 'State')} · ${esc(selected.license_number)}` : '—'],['Who they work with', (selected.populations || []).join(', ') || '—'],['Insurance / payment', (selected.insurance || []).join(', ') || '—'],['Specialties', (selected.specialties || []).join(', ') || '—'],['Services', (selected.services || []).join(', ') || '—'],['Modalities / approaches', (selected.approaches || []).join(', ') || '—'],['Requested plan', selected.requested_plan === 'advanced' ? 'Advanced' : 'Basic']]; $('reviewFields').innerHTML = rows.map(([label,value]) => `<div class="review-field"><dt>${label}</dt><dd>${label === 'Bio' ? esc(value) : value}</dd></div>`).join(''); $('reviewPlan').value = selected.plan || selected.requested_plan || 'basic'; }
async function load() { const { data: auth } = await supabase.auth.getSession(); if (!auth.session) { location.href = 'provider-login.html'; return; } const { data, error } = await supabase.rpc('admin_list_submissions'); if (error) { message(error.message, 'error'); $('submissionList').innerHTML = '<p class="muted">You do not have administrator access yet.</p>'; return; } submissions = data || []; renderList(); renderDetail(); }
function selectSubmission(id) { selected = submissions.find(p => p.id === id) || null; renderList(); renderDetail(); }
async function approve() { if (!selected) return; message('Approving profile for payment…'); const plan = $('reviewPlan').value === 'advanced' ? 'advanced' : 'basic'; const planResult = await supabase.rpc('admin_set_provider_plan', { target_provider_id: selected.id, target_plan: plan }); if (planResult.error) { message(planResult.error.message, 'error'); return; } const { error } = await supabase.rpc('admin_approve_provider', { target_provider_id: selected.id }); if (error) { message(error.message, 'error'); return; } message('Profile approved. Provider payment is now required before publication.', 'success'); submissions = submissions.filter(p => p.id !== selected.id); selected = null; renderList(); renderDetail(); }
async function requestChanges() { if (!selected) return; message('Returning profile to draft…'); const { error } = await supabase.rpc('admin_request_provider_changes', { target_provider_id: selected.id }); if (error) { message(error.message, 'error'); return; } message('Profile returned to draft. The provider can update and resubmit.', 'success'); submissions = submissions.filter(p => p.id !== selected.id); selected = null; renderList(); renderDetail(); }
$('approveProfile').addEventListener('click', approve); $('requestChanges').addEventListener('click', requestChanges); $('signOut').addEventListener('click', async () => { const { error } = await supabase.auth.signOut(); if (error) { message(error.message, 'error'); return; } location.replace('provider-login.html?signed_out=1'); }); await load();
